SVG_SHELL = (
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" '
    'width="{size}" height="{size}">{body}</svg>'
)


def render(d: str, factor: float) -> Image.Image:
    big = int(CANVAS * factor)
    # raw SVG body (with {color} placeholder) or a plain path d
    body = d if "{color}" in d else f'<path fill="{{color}}" d="{d}"/>'
    svg = SVG_SHELL.replace("{size}", str(big)).replace("{body}", body).replace("{color}", BRAND)
    out = subprocess.run(
        ["magick", "-background", "none", "svg:-", "png:-"],
        input=svg.encode(), capture_output=True, check=True,
    )
    im = Image.open(io.BytesIO(out.stdout)).convert("RGBA")
    if big >= CANVAS:  # center-crop oversized render
        side = (im.width - CANVAS) // 2
        im = im.crop((side, side, side + CANVAS, side + CANVAS))
    else:  # center-paste shrunk render
        canvas = Image.new("RGBA", (CANVAS, CANVAS), (0, 0, 0, 0))
        off = (CANVAS - big) // 2
        canvas.paste(im, (off, off))
        im = canvas
    return im.resize((FINAL, FINAL), Image.LANCZOS)


def main() -> None:
    os.makedirs(OUT, exist_ok=True)
    mapping = []
    for name, emoji_char, d, factor in ICONS:
        im = render(d, factor)
        path = os.path.join(OUT, f"{name}.png")
        im.save(path, "PNG")
        bbox = im.split()[3].getbbox()  # alpha-only: magick keeps RGB under transparent px
        assert bbox and bbox[0] > 0 and bbox[1] > 0 and bbox[2] < FINAL and bbox[3] < FINAL, name
        mapping.append((name, emoji_char, path))
        print(f"{name:12s} {emoji_char} -> {path} bbox={bbox}")
    with open(os.path.join(os.path.dirname(OUT), "mapping.txt"), "w") as f:
        for name, emoji_char, path in mapping:
            f.write(f"{name}.png\t{emoji_char}\n")


if __name__ == "__main__":
    main()
